import SwiftUI

/// The PWA's own line icons (_ICON, the tab icons, close/check/play), bundled as template SVGs
/// in Assets.xcassets (generated by Tools/gen-icons.py from jacked-pwa/index.html).
/// Tinted with foregroundStyle like text. Name without the "ic-" prefix.
struct JIcon: View {
    let name: String
    let size: CGFloat
    init(_ name: String, _ size: CGFloat = 18) { self.name = name; self.size = size }
    var body: some View {
        Image("ic-" + name).renderingMode(.template).resizable().scaledToFit()
            .frame(width: size, height: size).accessibilityHidden(true)
    }
}

/// Bridges an SF Symbol name to the PWA icon that stands in for it; unmapped names stay SF Symbols.
enum PWAIcon {
    static let map: [String: String] = [
        "xmark": "close", "checkmark": "tick", "play.fill": "play", "chevron.down": "chevron", "ellipsis": "dots",
        "ellipsis.circle": "dots", "pencil": "pencil", "trash": "trash", "medal.fill": "medal", "crown.fill": "crown",
        "star.fill": "starfill", "dumbbell": "dumbbell", "dumbbell.fill": "dumbbell", "trophy.fill": "trophy", "flame": "flame", "flame.fill": "flame",
        "hourglass": "hourglass", "calendar.badge.checkmark": "calendarCheck", "calendar": "calendar", "bed.double": "bed",
        "link": "link", "magnifyingglass": "search", "eye": "eye", "eye.slash": "eyeoff", "info.circle": "info",
        "exclamationmark.triangle.fill": "warning", "doc.on.clipboard": "clipboard", "arrow.up.arrow.down": "sort",
        "arrow.left.arrow.right": "replace", "arrow.up.circle.fill": "arrowUp", "square.grid.2x2": "tab-routines",
        "books.vertical": "tab-library", "house": "tab-home", "waveform.path.ecg": "tab-metrics", "person.2": "tab-friends",
        "heart.fill": "heart", "target": "target"]
}

/// Icon given as an SF Symbol name: shows the PWA's equivalent when there is one.
struct SFIcon: View {
    let sf: String; let size: CGFloat
    init(_ sf: String, _ size: CGFloat = 16) { self.sf = sf; self.size = size }
    var body: some View {
        if let n = PWAIcon.map[sf] { JIcon(n, size) } else { Image(systemName: sf).font(.system(size: size)) }
    }
}
